class CollaborationWriteCoordinator:
    """Coordinates agent/shell writes against file revisions and mutation leases."""

    def __init__(self, store: CollaborationStore, project_id: str, member_id: str, device_id: str = "agent"):
        self.store = store
        self.principal = CollaborationPrincipal(project_id, member_id, device_id, "agent", "", "agent", float("inf"))
        self.project_lock = self.store.project_mutation_lock(project_id)

    def write(self, relative: str, content: bytes, expected_revision: int, *, reason: str = "agent_write") -> dict:
        return self.store.write_file(self.principal, relative, content, expected_revision, reason=reason)

    def begin_task(self, session_id: str, task_text: str) -> dict:
        return self.store.begin_agent_task(
            self.principal,
            agent_id=f"agent:{session_id}",
            session_id=session_id,
            task_text=task_text,
        )

    def declare_intent(
        self,
        session_id: str,
        relative: str,
        *,
        intent: str,
        baseline_revision: int = 0,
    ) -> dict:
        agent_id = f"agent:{session_id}"
        result = self.store.declare_intent(
            self.principal,
            relative,
            agent_id=agent_id,
            intent=intent,
            baseline_revision=baseline_revision,
        )
        try:
            self.store.record_agent_task_evidence(
                self.principal,
                agent_id=agent_id,
                session_id=session_id,
                kind="file_intent",
                summary=f"Declared {intent} intent for {result.get('path', relative)} at revision {int(baseline_revision)}.",
                path=str(result.get("path", relative) or relative),
                revision=int(baseline_revision),
            )
        except Exception:
            pass
        return result

    def record_evidence(
        self,
        session_id: str,
        *,
        kind: str,
        summary: str,
        path: str = "",
        revision: int = 0,
    ) -> dict:
        try:
            return self.store.record_agent_task_evidence(
                self.principal,
                agent_id=f"agent:{session_id}",
                session_id=session_id,
                kind=kind,
                summary=summary,
                path=path,
                revision=revision,
            )
        except Exception as exc:
            return {"ok": False, "skipped": True, "reason": _collaboration_public_text(exc, 160)}

    def publish_blackboard_update(
        self,
        session_id: str,
        *,
        section: str,
        content: str,
        status: str = "",
    ) -> dict:
        return self.store.record_agent_blackboard_update(
            self.principal,
            agent_id=f"agent:{session_id}",
            session_id=session_id,
            section=section,
            content=content,
            status=status,
        )

    def initialize_task_plan(self, session_id: str, steps: list[str]) -> dict:
        clean_steps = [
            _collaboration_public_text(step, 280)
            for step in list(steps or [])[:20]
            if _collaboration_public_text(step, 280)
        ]
        if len(clean_steps) < 2:
            return {"ok": True, "skipped": True, "reason": "insufficient_coordination_steps"}
        content = "\n".join(f"{index}. {step}" for index, step in enumerate(clean_steps, 1))
        return self.store.record_agent_blackboard_update(
            self.principal,
            agent_id=f"agent:{session_id}",
            session_id=session_id,
            section="plan_steps",
            content=content,
            status="in_progress",
            initialize_only=True,
        )

    def heartbeat(
        self,
        session_id: str,
        *,
        status: str = "running",
        current_file: str = "",
        tool_summary: str = "",
        result_summary: str = "",
    ) -> dict:
        return self.store.update_agent(
            self.principal,
            agent_id=f"agent:{session_id}",
            session_id=session_id,
            status=status,
            current_file=current_file,
            tool_summary=tool_summary,
            result_summary=result_summary,
        )

    def finish_task(self, session_id: str, *, status: str, result_summary: str) -> dict:
        return self.store.finish_agent_task(
            self.principal,
            agent_id=f"agent:{session_id}",
            session_id=session_id,
            status=status,
            result_summary=result_summary,
        )

    def mutation_lease(self):
        return self.project_lock

    def begin_process(self) -> dict[str, dict]:
        root = self.store.project_workspace(self.principal.project_id)
        before: dict[str, dict] = {}
        for row in self.store.list_documents(self.principal.project_id, limit=2000):
            path = root / row["path"]
            try:
                document = self.store.read_document(self.principal.project_id, row["path"])
                before[row["path"]] = {
                    "revision": int(document["revision"]),
                    "hash": hashlib.sha256(path.read_bytes()).hexdigest(),
                }
            except Exception:
                continue
        return before

    def finish_process(self, before: dict[str, dict]) -> list[dict]:
        root = self.store.project_workspace(self.principal.project_id)
        results: list[dict] = []
        seen: set[str] = set()
        for row in self.store.list_documents(self.principal.project_id, limit=2000):
            rel = row["path"]
            path = root / rel
            try:
                content = path.read_bytes()
            except OSError:
                continue
            seen.add(rel)
            digest = hashlib.sha256(content).hexdigest()
            prior = before.get(rel, {})
            if digest == prior.get("hash"):
                continue
            results.append(
                self.store.adopt_process_write(
                    self.principal,
                    rel,
                    content,
                    int(prior.get("revision", 0)),
                )
            )
        # New files are not in the document catalog yet.
        for path in sorted(root.rglob("*")):
            if path.is_symlink() or not path.is_file():
                continue
            rel = path.relative_to(root).as_posix()
            if rel in seen or rel in before:
                continue
            results.append(self.store.adopt_process_write(self.principal, rel, path.read_bytes(), 0))
        # A process may intentionally remove a known file. Because the project
        # mutation lease is still held, commit that deletion now rather than
        # letting the external-write watcher turn it into an empty B branch.
        for rel, prior in before.items():
            if rel in seen:
                continue
            path = root / rel
            if path.exists():
                continue
            results.append(
                self.store.adopt_process_delete(
                    self.principal,
                    rel,
                    int(prior.get("revision", 0)),
                )
            )
        return results

    def scan_after_process(self, before: dict[str, tuple[int, int]]) -> list[dict]:
        root = self.store.project_workspace(self.principal.project_id)
        changes: list[dict] = []
        for row in self.store.list_documents(self.principal.project_id, limit=2000):
            path = root / row["path"]
            state = (int(row["size"]), int(path.stat().st_mtime_ns))
            if before.get(row["path"]) != state:
                changes.append(row)
        return changes
